import {$, show} from './dom.js';
import {mountDelivery} from './delivery.js';
import {mountCorporate} from './corporate.js';
import {guided, nudge} from './forms.js';
export function mountCommerce({storefront, inquiry, motion, funnel, favorites}) {
const products=storefront.products();
// Corazón dibujado (SVG): los caracteres de corazón se vuelven emoji en iPhone.
const FAVS='Favoritos',HEART='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.4s-7.6-4.6-7.6-10.2A4.3 4.3 0 0 1 12 7.6a4.3 4.3 0 0 1 7.6 2.6c0 5.6-7.6 10.2-7.6 10.2z"/></svg>';
// Producto insignia (`highlight` en el catálogo): marco con una luz que lo recorre y chispas sobre la foto. Todo decorativo.
const RING='<span class="jewel-ring" aria-hidden="true"><i></i></span>',SPARKS='<span class="jewel-sparks" aria-hidden="true"><i></i><i></i><i></i></span>';
const favLabel=(p,on)=>`${on?'Quitar':'Guardar'} ${p.name} ${on?'de':'en'} favoritos`;
function fav(p,text=false){const on=favorites.has(p.id);return `<button type="button" class="fav${text?' fav-text':''}" data-fav="${p.id}" aria-pressed="${on}" aria-label="${favLabel(p,on)}">${HEART}${text?`<span>${on?'Guardado':'Guardar'}</span>`:''}</button>`}
function photo(p,detail=false){const n=products.indexOf(p)-1,cell=n%6;return `<div class="${detail?'detail-photo ':''}food-photo"${detail&&p.image?` style="background-image:url('assets/sm/${p.image}')"`:''}><img src="assets/${p.image&&!detail?'sm/'+p.image:(p.image || (n<0?'hero.webp':'catalog.webp'))}" ${p.image&&!detail?`srcset="assets/sm/${p.image} 520w, assets/${p.image} 1200w" sizes="(max-width:760px) 46vw, (max-width:1100px) 31vw, 380px" `:''}decoding="async" ${p.image&&p.focus?`style="object-position:${p.focus}" `:''}${p.image || n<0?'':`class="sprite" style="left:-${cell%3*100}%;top:-${Math.floor(cell/3)*100}%"`} alt="${p.name}${p.image?'':', imagen ilustrativa'}" loading="lazy"></div>`}
let active='Todos',lastAmount=0;
const corporateServices=storefront.corporateServices(),corporateOf=p=>corporateServices.find(s=>s.options.some(o=>o.id===p.id&&o.prompt));
// Empresas: el mismo aviso, con las mismas palabras, en cada punto donde alguien puede dudar por dónde seguir.
const callout=(title,text,attrs)=>`<div class="corp-callout-text"><strong>${title}</strong><small>${text}</small></div><button type="button" class="corp-callout-btn" ${attrs}>Cotizar para mi empresa</button>`;
$('#business-services').innerHTML=corporateServices.map(s=>`<button type="button" class="business-item" data-corporate="${s.id}"><span><strong>${s.label}</strong><small>${s.options.length>1?s.options.map(o=>o.name).join(' · '):s.options[0].description}</small></span><i class="ar" aria-hidden="true"></i></button>`).join('');
const lines=storefront.lines(),money=storefront.formatPrice,linesOf=p=>lines.filter(l=>l.product===p);
function priceText(p){const from=storefront.startingPrice(p);return from===null?'Precio por cotizar':(p.presentations.length>1?'Desde ':'')+money(from)}
function priceHtml(p){const from=storefront.startingPrice(p);return from===null?'Por cotizar':(p.presentations.length>1?'<small>Desde</small> ':'')+money(from)}
// Pedido mínimo que conviene avisar en la tarjeta: el del producto o el de su presentación más económica.
const minOf=p=>p.min||linesOf(p).filter(l=>Number.isFinite(l.price)).sort((a,b)=>a.price-b.price)[0]?.min||null;
function addControl(p){const [first,...rest]=linesOf(p);return rest.length?`<button class="add" data-detail="${p.id}" aria-label="Elegir presentación de ${p.name}">+</button>`:`<button class="add" data-add="${first.key}" aria-label="Agregar ${p.name} a mi selección">+</button>`}
function gallery(p){return p.gallery.length?`<div class="gallery">${[p.image,...p.gallery].map((f,i)=>`<button data-photo="${f}" aria-label="Ver foto ${i+1} de ${p.name}" aria-pressed="${i===0}"><img src="assets/sm/${f}" alt="" loading="lazy"></button>`).join('')}</div>`:''}
function fitKey(p){const n=funnel.guests();return n&&storefront.sizes(p)>1?storefront.fit(p,n)?.key:null}
function rows(p){const fit=fitKey(p);let group=null;return linesOf(p).map(l=>{const pp=storefront.perPortion(l.price,l.label),head=l.group&&l.group!==group?`<li class="pres-group">${l.group}</li>`:'';group=l.group;return `${head}<li${l.key===fit?' class="fit"':''} data-key="${l.key}"><div><strong>${l.label}</strong>${l.note?`<small>${l.note}</small>`:''}${l.min?`<small class="row-min">Mínimo ${l.min} unidades</small>`:''}${pp?`<small class="per-portion">≈ ${money(pp)} por porción</small>`:''}<em class="fit-badge">Ideal para tu grupo</em></div><span class="presentation-price">${l.price===null?'Por cotizar':money(l.price)}</span><button class="add add-row" data-add="${l.key}" aria-label="Agregar ${p.name}, ${l.label}, a mi selección"><span class="add-plus" aria-hidden="true">+</span><span class="add-text">${l.min?'Agregar '+l.min:'Agregar'}</span></button></li>`}).join('')}
function options(p){const [first]=linesOf(p),sized=storefront.sizes(p)>1;return (first.label===null?`<button class="button" data-add="${first.key}">${p.min?`Agregar ${p.min} a mi selección`:'Agregar a mi selección'} <span>+</span></button>`:`${sized?funnel.guestsHtml():''}<ul class="presentations">${rows(p)}</ul>`)+`<button type="button" class="plain-link ask" data-ask="${p.id}">${sized?'¿Dudas con el tamaño? Pregúntale a Nore':'¿Alguna duda? Pregúntale a Nore'} <span class="ar" aria-hidden="true"></span></button>`+(corporateOf(p)?`<div class="corp-callout">${callout('¿Es para tu empresa o un evento?','Cotízalo por cantidad, con fecha y lugar de entrega.',`data-corporate="${corporateOf(p).id}" data-option="${p.id}"`)}</div>`:'')+funnel.suggestHtml(storefront.related([p.id],2),'Va muy bien con')}
function applyFit(){const box=$('#product-detail'),p=products.find(x=>x.id===box.dataset.for);if(!p)return;box.querySelectorAll('.guests button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.guests)===funnel.guests())));const fit=fitKey(p);box.querySelectorAll('.presentations li').forEach(li=>li.classList.toggle('fit',li.dataset.key===fit));box.querySelector('.presentations .fit')?.scrollIntoView({block:'nearest',behavior:'smooth'})}
function detailHtml(p){return `<div class="detail-media">${photo(p,true)}${p.highlight?SPARKS:''}${gallery(p)}</div><div class="detail-body"><div class="detail-top"><p class="eyebrow${p.highlight?' jewel-chip':''}">${p.highlight||p.category}</p>${fav(p,true)}</div><h2>${p.name}</h2><p class="detail-price">${priceHtml(p)}</p>${p.min?`<p class="detail-min">Pedido mínimo: ${p.min} unidades</p>`:''}<p class="detail-lead">${p.detail}</p>${p.includes.length?`<div class="detail-includes"><p class="suggest-title">Incluye</p><ul>${p.includes.map(item=>`<li>${item}</li>`).join('')}</ul>${p.extra?`<p class="detail-extra">${p.extra}</p>`:''}</div>`:''}${options(p)}${p.steps?`<details class="detail-steps"><summary>${p.steps.title}</summary><ol>${p.steps.items.map(item=>`<li>${item}</li>`).join('')}</ol></details>`:''}<p class="muted">Imagen ilustrativa. Ingredientes, alérgenos y disponibilidad por confirmar.${storefront.startingPrice(p)!==null?' Precios de referencia; se confirman al cotizar.':''}</p></div>`}
function card(p){return `<article class="product${p.highlight?' jewel':''}" data-product="${p.id}" data-detail="${p.id}" data-rv="card">${p.highlight?RING:''}<button class="product-image" data-detail="${p.id}" aria-label="Ver ${p.name}">${photo(p)}${p.highlight?SPARKS:''}<span class="tag">${p.tag}</span></button><div class="fav-slot">${fav(p)}</div>${p.highlight?`<span class="jewel-chip">${p.highlight}</span>`:''}<div class="product-info"><div class="product-top"><h3>${p.name}</h3>${addControl(p)}</div><p>${p.description}</p><p class="price">${priceHtml(p)}${minOf(p)?`<small class="price-min">Mínimo ${minOf(p)}</small>`:''}</p><button class="detail-link" data-detail="${p.id}">Descubrir y cotizar <i class="ar" aria-hidden="true"></i></button></div></article>`}
// En «Todos» la colección va por secciones, cada una con su título; al filtrar, la lista sale corrida.
function renderProducts(){ const list=active===FAVS?products.filter(p=>favorites.has(p.id)):storefront.filter(active);const forTeams=active===all||active===FAVS?[]:corporateServices.filter(s=>s.options.some(o=>o.prompt&&o.category===active)),note=$('#catalog-corporate');note.hidden=!forTeams.length;note.innerHTML=forTeams.length?callout('¿Es para tu empresa o un evento?',`Cotiza ${forTeams.map(s=>s.label.toLowerCase()).join(' y ')} por cantidad.`,`data-corporate="${forTeams[0].id}"`):'';$('#products').classList.toggle('filtered',active!=='Todos');$('#catalog-status').textContent=active==='Todos'?`${products.length} formas de endulzar tu día`:active===FAVS&&!list.length?'Aún no tienes favoritos':`${active} · ${list.length} ${active===FAVS?(list.length===1?'guardado':'guardados'):(list.length===1?'opción':'opciones')}`; $('#products').innerHTML=!list.length?`<div class="fav-empty"><span class="bag-empty-seal" aria-hidden="true">${HEART}</span><h3>Guarda lo que te enamore.</h3><p>Toca el corazón de un producto y lo encontrarás aquí en tu próxima visita. Se guarda solo en este dispositivo.</p><button class="button" type="button" data-show-all>Ver toda la colección <span class="ar" aria-hidden="true"></span></button></div>`:(active===all?sections.map(name=>`<h3 class="group-title">${name}</h3><div class="group">${list.filter(p=>p.category===name).map(card).join('')}</div>`).join(''):list.map(card).join(''));window.dispatchEvent(new Event('nore:catalog'));}
const [all,...sections]=storefront.categories();
$('.filters').innerHTML=[all,FAVS,...sections].map(c=>`<button data-category="${c}" aria-pressed="${c===active}">${c}</button>`).join('');
function choose(b){active=b.dataset.category;$('.filters').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));motion.select(b);motion.transition(renderProducts)}
$('.filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b||b.getAttribute('aria-pressed')==='true')return;choose(b)});
const chip=name=>[...$('.filters').querySelectorAll('[data-category]')].find(b=>b.dataset.category===name),go=name=>{const b=chip(name);if(b&&b.getAttribute('aria-pressed')!=='true')choose(b)};
function toggleFav(b){const id=b.dataset.fav,p=products.find(x=>x.id===id),on=favorites.toggle(id);document.querySelectorAll(`[data-fav="${id}"]`).forEach(x=>{x.setAttribute('aria-pressed',String(on));x.setAttribute('aria-label',favLabel(p,on));const t=x.querySelector('span');if(t)t.textContent=on?'Guardado':'Guardar'});motion.pop(b.querySelector('svg'),1.35);$('#toast').textContent=p.name+(on?' guardado en favoritos':' quitado de favoritos');if(active===FAVS&&!on)motion.transition(renderProducts)}
document.querySelector('[data-favorites]')?.addEventListener('click',()=>go(FAVS));
function bagRow(key,q){const l=lines.find(x=>x.key===key),p=l.product,what=p.name+(l.label?', '+l.label:'');return `<div class="bag-item" data-row="${key}"><span class="bag-thumb">${p.image?`<img src="assets/sm/${p.image}" alt="" width="64" height="64" decoding="async">`:'<i aria-hidden="true">✦</i>'}</span><div class="bag-info"><h3>${p.name}</h3>${l.label?`<small>${l.label}</small>`:''}<small class="bag-unit">${l.price===null?'A cotizar':money(l.price)+' c/u'}</small>${l.min||p.min?`<small class="bag-min-note">Pedido mínimo: ${l.min||p.min}</small>`:''}</div><div class="qty"><button data-qty="${key}" data-change="-1" aria-label="Quitar una unidad de ${what}">−</button><span>${q}</span><button data-qty="${key}" data-change="1" aria-label="Añadir una unidad de ${what}">+</button></div></div>`}
let bagKeys=null;
function renderBag(){const basket=storefront.entries(),box=$('#bag-items'),keys=[...basket.keys()].join('|');let total=0;basket.forEach(q=>total+=q);$('#count').textContent=total;$('#open-bag').setAttribute('aria-label',`Ver mi selección, ${total} productos`);
if(basket.size&&keys===bagKeys)box.querySelectorAll('[data-row]').forEach(row=>{row.querySelector('.qty span').textContent=basket.get(row.dataset.row)});
else box.innerHTML=basket.size?[...basket].map(([key,q])=>bagRow(key,q)).join(''):'<div class="bag-empty"><span class="bag-empty-seal" aria-hidden="true">✦</span><h3>Aún no hay antojos aquí.</h3><p>Explora la colección y agrega lo que te enamore. Nada se cobra en esta página.</p><button class="button" id="explore">Explorar la colección <span class="ar" aria-hidden="true"></span></button></div>';
bagKeys=keys;const short=storefront.minimums(),minBox=$('#bag-min');minBox.hidden=!short.length;minBox.innerHTML=short.map(i=>{const gap=i.required-i.current;return `<div class="min-issue"><div><strong>${i.product.name}${i.label?' · '+i.label:''}: el pedido mínimo es de ${i.required} unidades</strong><small>Llevas ${i.current}. ${gap===1?'Te falta 1.':'Te faltan '+gap+'.'}</small></div><button type="button" data-topup="${i.key}" data-n="${gap}">Completar a ${i.required}</button></div>`}).join('');const teams=corporateServices.map(s=>{const picked=[...basket].map(([key,q])=>({p:lines.find(l=>l.key===key).product,q})).filter(x=>s.options.some(o=>o.id===x.p.id));return {id:s.id,quantity:picked.reduce((n,x)=>n+x.q,0),options:[...new Set(picked.map(x=>x.p.id))]}}).filter(x=>x.quantity),bagNote=$('#bag-corporate');const showTeams=[...basket.keys()].some(key=>corporateOf(lines.find(l=>l.key===key).product));bagNote.hidden=!showTeams;bagNote.dataset.items=JSON.stringify(teams);bagNote.innerHTML=showTeams?callout('¿Es un pedido para tu empresa?','Pásalo a una cotización por cantidad: llevamos lo que ya elegiste.','data-corporate data-from-bag'):'';const sum=storefront.total();$('#bag-foot').hidden=!basket.size;$('#bag-total').innerHTML=sum.amount?`<span>${sum.complete?'Total de referencia':'Total de lo que tiene precio'}</span><strong>${money(sum.amount)}</strong>`:'<span>Total</span><strong class="quote">A cotizar</strong>';if(sum.amount)motion.count($('#bag-total strong'),lastAmount,sum.amount,money);lastAmount=sum.amount;window.dispatchEvent(new CustomEvent('nore:bag',{detail:{count:total,amount:sum.amount,complete:sum.complete,productIds:[...basket.keys()].map(k=>lines.find(l=>l.key===k).product.id)}}))}
window.addEventListener('nore:add',e=>{const d=e.detail;if(d.context)storefront.setContext(d.context);add(d.key,d.origin)});
function add(key,origin){const n=storefront.add(key);renderBag();const l=lines.find(x=>x.key===key),name=l.product.name+(l.label?' · '+l.label:''),text=n>1?`${n} × ${name} (pedido mínimo)`:name;motion.flyToBag(origin,l.product.image?`assets/sm/${l.product.image}`:null);motion.confirm(origin);document.querySelectorAll('dialog[open]').forEach(d=>motion.closeDialog(d,{fly:false}));$('#toast').textContent=text+(n>1?' añadidas a tu selección':' añadido a tu selección');window.dispatchEvent(new CustomEvent('nore:added',{detail:{text}}))}
document.addEventListener('click',e=>{const f=e.target.closest('[data-fav]');if(f){toggleFav(f);return}const co=e.target.closest('[data-corporate]');if(co){show('#corporate-dialog');if('fromBag' in co.dataset)corporate.fill(JSON.parse($('#bag-corporate').dataset.items||'[]'));else corporate.prepare(co.dataset.corporate,co.dataset.option);return}if(e.target.closest('[data-go-collection]')){motion.closeDialog($('#corporate-dialog'));$('#coleccion').scrollIntoView({behavior:'smooth'});return}if(e.target.closest('[data-show-all]')){go(all);return}const a=e.target.closest('[data-add]');if(a){add(a.dataset.add,a);return}const g=e.target.closest('[data-photo]');if(g){const img=$('#product-detail .detail-photo img');img.parentElement.style.backgroundImage=`url('assets/sm/${g.dataset.photo}')`;img.src='assets/'+g.dataset.photo;motion.settle(img);g.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===g)));return}const d=e.target.closest('[data-detail]');if(d){const p=products.find(x=>x.id===d.dataset.detail),dialog=$('#product-dialog'),box=$('#product-detail'),inPlace=dialog.open;box.dataset.for=p.id;box.classList.toggle('jewel',Boolean(p.highlight));box.innerHTML=detailHtml(p);show('#product-dialog');if(inPlace)motion.swap(box);else motion.openProduct(d.closest('.product')?.querySelector('.product-image'),dialog);return}const gu=e.target.closest('[data-guests]');if(gu){funnel.setGuests(Number(gu.dataset.guests));applyFit();return}const ask=e.target.closest('[data-ask]');if(ask){const p=products.find(x=>x.id===ask.dataset.ask),n=funnel.guests();contact(`Hola, Nore. Me interesa «${p.name}». ¿Qué tamaño o presentación me recomiendas${n?` para unas ${n} personas`:''}?`);return}const up=e.target.closest('[data-topup]');if(up){storefront.change(up.dataset.topup,Number(up.dataset.n));renderBag();motion.pop($('#count'));return}const q=e.target.closest('[data-qty]');if(q){const id=q.dataset.qty,delta=Number(q.dataset.change),row=q.closest('.bag-item');if(row?.dataset.leaving)return;const apply=()=>{motion.flip($('#bag-items'),()=>{storefront.change(id,delta);renderBag()});motion.pop(row?.isConnected?row.querySelector('.qty span'):null,1.25);motion.pop($('#count'))};if(delta<0&&storefront.entries().get(id)===1&&row){row.dataset.leaving='1';motion.exit(row).then(apply)}else apply();return}if(e.target.closest('#explore')){motion.closeDialog($('#bag-dialog'));$('#coleccion').scrollIntoView({behavior:'smooth'})}});
document.querySelectorAll('.close').forEach(b=>b.addEventListener('click',()=>motion.closeDialog(b.closest('dialog'))));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)motion.closeDialog(d)}}));
$('#open-bag').onclick=()=>{renderBag();show('#bag-dialog')};$('#custom-open').onclick=()=>show('#custom-dialog');
const intents=[...document.querySelectorAll('[data-intent]')],greeting='Hola, Nore. Me gustaría conocer más sobre tus productos y recibir ayuda para elegir un detalle especial.',presets={regalo:'Hola, Nore. Quiero sorprender a alguien especial. ¿Me ayudas a elegir un regalo y conocer las opciones de presentación?',celebracion:'Hola, Nore. Estoy preparando una celebración. Me gustaría conocer las opciones de tortas y creaciones personalizadas.',antojo:'Hola, Nore. Quiero darme un gusto. ¿Qué postres, alfajores o tartas tienen disponibles?'};
let flow='consulta',last=null;
const consentOk=()=>{$('#consent-error').hidden=true;$('#data-consent-line').classList.remove('invalid')};$('#data-consent').addEventListener('change',consentOk);
function contact(message,kind='consulta'){flow=kind;$('#message').value=message;intents.forEach(x=>x.setAttribute('aria-pressed','false'));$('#data-consent').checked=false;consentOk();$('#data-consent-line').hidden=!inquiry.enabled;$('#copy-status').textContent='';$('#contact-status').textContent=inquiry.enabled?'Continuarás en WhatsApp para confirmar los detalles con Nore.':'WhatsApp estará disponible próximamente. Por ahora puedes copiar tu consulta; no se envía ningún pedido.';$('#send-message').innerHTML=inquiry.enabled?'Continuar en WhatsApp <span class="ar" aria-hidden="true"></span>':'Copiar solicitud <span class="ar" aria-hidden="true"></span>';show('#chat-dialog')}
$('#chat-open').onclick=()=>contact(greeting);document.querySelectorAll('[data-chat]').forEach(b=>b.addEventListener('click',()=>contact(greeting)));
// En el teléfono el mensaje lleva iconos; en el computador va limpio (WhatsApp de escritorio no siempre los muestra bien).
storefront.setContext({emoji:matchMedia('(hover: none) and (pointer: coarse)').matches});
// De la selección se pasa por la entrega (recoger o domicilio) y de ahí al mensaje ya armado.
$('#quote-button').onclick=()=>{if(storefront.minimums().length){const box=$('#bag-min');box.scrollIntoView({block:'center',behavior:'smooth'});nudge(box);return}show('#delivery-dialog')};const delivery=mountDelivery({storefront,onReady:()=>contact(storefront.quote(),'pedido')});
$('#date').min=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
const checkIdea=guided($('#custom-form'),{date:'Elige la fecha deseada.',people:'Escribe para cuántas personas.'});
$('#custom-form').onsubmit=e=>{e.preventDefault();if(!checkIdea())return;contact(storefront.customize(Object.fromEntries(new FormData(e.target))),'idea')};
// Eventos y empresas: la solicitud ya llega armada como mensaje.
const corporate=mountCorporate({storefront,onReady:message=>contact(message,'empresa')});
// WhatsApp ya se abrió con el mensaje. La página no sabe si la persona lo envió: por eso agradece, deja todo limpio para
// un pedido nuevo y guarda (solo en memoria) lo anterior, por si no alcanzó a enviarlo y quiere recuperarlo.
function sent(message){const order=flow==='pedido';last={kind:flow,message,store:storefront.snapshot(),delivery:delivery.snapshot(),guests:funnel.guests()};
if(order){storefront.clear();funnel.setGuests(null);delivery.reset();renderBag()}if(flow==='idea')$('#custom-form').reset();if(flow==='empresa')corporate.reset();
$('#thanks-text').textContent=order?'Abrimos WhatsApp con tu pedido listo. Envíalo desde allí y Nore te confirma precio, disponibilidad y entrega. Aquí ya puedes empezar un pedido nuevo cuando quieras.':'Abrimos WhatsApp con tu mensaje listo. Envíalo desde allí y Nore te responde con gusto.';
$('#thanks-again-label').textContent=order?'Hacer otro pedido':'Seguir viendo la colección';$('#thanks-recover').textContent=order?'¿No alcanzaste a enviarlo? Recuperar mi pedido':'¿No alcanzaste a enviarlo? Ver mi mensaje otra vez';show('#thanks-dialog')}
$('#thanks-again').onclick=()=>{motion.closeDialog($('#thanks-dialog'));$('#coleccion').scrollIntoView({behavior:'smooth'})};
$('#thanks-recover').onclick=()=>{if(!last)return;if(last.kind==='pedido'){storefront.restore(last.store);funnel.setGuests(last.guests);delivery.restore(last.delivery);renderBag()}contact(last.message,last.kind)};
$('#send-message').onclick=async()=>{
  const message=$('#message').value,result=await inquiry.deliver(message,$('#data-consent').checked);
  if(result==='opened')sent(message);
  if(result==='consent-required'){const line=$('#data-consent-line');$('#consent-error').hidden=false;line.classList.add('invalid');line.scrollIntoView({block:'center',behavior:'smooth'});nudge(line);$('#data-consent').focus({preventScroll:true});}
  if(result==='copied')$('#copy-status').textContent='Solicitud copiada. No se ha enviado ningún pedido.';
  if(result==='copy-unavailable'){$('#message').focus();$('#message').select();$('#copy-status').textContent='Selecciona y copia el texto para conservar tu solicitud.';}
};
$('#year').textContent=new Date().getFullYear();renderProducts();renderBag();

// Motivo de la consulta. Un saludo general se cambia por el del motivo; una consulta ya armada (selección, pedido a medida,
// pregunta por un producto o texto que la persona editó) se conserva y solo gana, cambia o pierde su línea «Motivo:».
intents.forEach(b=>b.onclick=()=>{const box=$('#message'),text=box.value.trim(),on=b.getAttribute('aria-pressed')==='true';intents.forEach(x=>x.setAttribute('aria-pressed',String(x===b&&!on)));if(!text||text===greeting||Object.values(presets).includes(text)){box.value=on?greeting:presets[b.dataset.intent];return}box.value=storefront.withReason(box.value,on?'':b.textContent.trim());box.scrollTop=box.scrollHeight});

}
